/* ========== LEVEL 5 · MATHS (university years 3–4) ========== */
/* one-delayed-group point kinetics: exact solution for a step (n0 = 1) */
var PK={b:0.0065,L:2e-5,l:0.08};
function pkRoots(r){var a=PK.L,b=PK.L*PK.l+PK.b-r,c=-r*PK.l,d=Math.sqrt(b*b-4*a*c);return [(-b+d)/(2*a),(-b-d)/(2*a)]}
function pkExact(r,t){var w=pkRoots(r),A1=(r/PK.L-w[1])/(w[0]-w[1]);return A1*Math.exp(w[0]*t)+(1-A1)*Math.exp(w[1]*t)}
/* finite-difference power iteration for a bare slab (one group), cached by iteration count */
var FDC={};
function fdPower(n){if(FDC[n])return FDC[n];var N=49,a=100,h=a/(N+1),D=1,Sa=0.02,nSf=0.0225,phi=[],k=1,i,it;
 for(i=0;i<N;i++){var x=(i+1)*h;phi.push(Math.pow(x/a,3))}
 for(it=0;it<n;it++){var s=phi.map(function(f){return nSf*f/k}),cp=[],dp=[],off=-D/(h*h),dg=2*D/(h*h)+Sa;
  for(i=0;i<N;i++){var den=dg-(i?off*cp[i-1]:0);cp.push(off/den);dp.push((s[i]-(i?off*dp[i-1]:0))/den)}
  var nw=new Array(N);nw[N-1]=dp[N-1];for(i=N-2;i>=0;i--)nw[i]=dp[i]-cp[i]*nw[i+1];
  var so=0,sn=0;for(i=0;i<N;i++){so+=phi[i];sn+=nw[i]}k=k*sn/so;phi=nw}
 var mx=Math.max.apply(null,phi);FDC[n]={phi:phi.map(function(f){return f/mx}),k:k,h:h};return FDC[n]}
/* Way–Wigner decay heat fraction: t after shutdown, T operating time (s) */
function wayW(t,T){return 0.066*(Math.pow(t,-0.2)-Math.pow(t+T,-0.2))}
function sciH(v){var e=Math.floor(Math.log10(Math.abs(v))),m=v/Math.pow(10,e);if(m>=9.95){m/=10;e++}return m.toFixed(1)+' × 10<sup>'+(e<0?'−'+(-e):e)+'</sup>'}
function tfmt(s){return s<120?s.toFixed(0)+' s':s<7200?(s/60).toFixed(0)+' min':s<172800?(s/3600).toFixed(1)+' h':(s/86400).toFixed(0)+' days'}

U({id:'m5-1',track:'maths',level:5,title:'Point kinetics',icon:'dn/dt',color:'#7F77DD',desc:'The coupled equations for neutrons and precursors, solving them numerically, and the inhour equation.',lessons:[
LH('m5-1-1','The point kinetics equations',10,'Two coupled differential equations that describe how reactor power changes with time.',[
RM(`<ul><li><b>β</b>: delayed neutron fraction, 0.0065 for U-235 (Level 4 Theory).</li><li>Precursors decay with constant λ; the parent–daughter equations (Level 4 Maths).</li><li><b>Λ</b> (generation time without delayed neutrons) is about 2 × 10⁻⁵ s in a PWR.</li></ul>`),
T(`<h3>Two populations</h3><p>Treat the whole core as one point, and track two things: the neutron population <b>n</b> and the precursor population <b>C</b>. Using one averaged group of precursors:</p><div class="eq">dn/dt = ((ρ − β)/Λ) n + λC<br>dC/dt = (β/Λ) n − λC</div>${KY([['n','neutron population (∝ power)',''],['C','delayed-neutron precursors',''],['ρ','reactivity','(fraction; 100 pcm = 0.001)'],['β','delayed neutron fraction','0.0065'],['Λ','prompt generation time','s'],['λ','one-group precursor decay constant (about 0.08)','s⁻¹']])}`),
W('flipCards',{cards:[['((ρ − β)/Λ) n','Prompt neutrons: each generation multiplies by (1 + ρ), but the fraction β is held back as precursors. If ρ < β, this term alone would make n fall.'],['λC','Delayed neutrons arriving as precursors decay. This is what holds n up.'],['(β/Λ) n','New precursors made by fission each second.'],['−λC','Precursors lost as they decay (and emit their delayed neutron).']]},`Flip each card to see what each term means.`),
W('stepCalc',{steps:['At steady state (ρ = 0), both derivatives are zero.','From the second equation: (β/Λ) n₀ = λC₀','So <div class="eq">C₀ = β n₀ ÷ (λΛ)</div>','Check the first: (−β/Λ) n₀ + λ × βn₀/(λΛ) = 0 ✓','With Λ = 2 × 10⁻⁵ s and λ = 0.08 s⁻¹: C₀ ≈ 4,000 n₀. There are far more precursors than neutrons: a huge "reservoir".']},`Find the steady state.`),
N(`n₀ = 1, β = 0.0065, λ = 0.08 s⁻¹, Λ = 2 × 10⁻⁵ s. What is C₀? (nearest whole number)`,4063,0.01,'',`0.0065 ÷ (0.08 × 2 × 10⁻⁵) = 0.0065 ÷ 1.6 × 10⁻⁶ = 4,063.`),
QE(`For the parent–daughter equations, the daughter's production term is…`,[`λ<sub>P</sub>N<sub>P</sub>`,`−λ<sub>D</sub>N<sub>D</sub>`,`zero`,`N<sub>P</sub>/λ`],0,`Level 4 Maths: same structure as dC/dt here.`),
T(`<h3>Key points</h3><ul><li><b>Point kinetics</b>: dn/dt = ((ρ − β)/Λ)n + λC; dC/dt = (β/Λ)n − λC.</li><li>Steady state: <b>C₀ = βn₀/(λΛ)</b>, thousands of times n₀.</li><li>Real codes use six precursor groups; one group shows the main behaviour.</li></ul>`)]),
LH('m5-1-2','Solving numerically: Euler and stiffness',10,'The simplest way to step a differential equation forward in time, and why it can explode.',[
RM(`<ul><li>The point kinetics equations.</li><li>Gradient = rate of change (Level 2 Maths).</li></ul>`),
T(`<h3>Euler's method</h3><p>If you know the value and its rate of change now, step forward a small time Δt:</p><div class="eq">y<sub>new</sub> = y<sub>old</sub> + Δt × (dy/dt)<sub>old</sub></div><p>Repeat, thousands of times. It's how a computer "solves" equations that have no neat formula.</p>`),
W('stepCalc',{steps:['dy/dt = −2y, y(0) = 1, Δt = 0.1','Step 1: y = 1 + 0.1 × (−2 × 1) = <b>0.8</b>','Step 2: y = 0.8 + 0.1 × (−1.6) = <b>0.64</b>','Step 3: y = 0.64 + 0.1 × (−1.28) = <b>0.512</b>','Exact at t = 0.3: e<sup>−0.6</sup> = 0.549. Close, and smaller Δt gets closer.']},`Do three Euler steps by hand.`),
T(`<h3>Stiffness</h3><p>Point kinetics has two very different time scales: a prompt one (about Λ/β ≈ 3 milliseconds) and a delayed one (tens of seconds). Equations like this are called <b>stiff</b>.</p><p>For Euler's method, each step multiplies the fast part by about (1 − Δt × β/Λ). If Δt is too big, that number is less than −1, and the errors flip sign and grow every step.</p>`),
W('odeSim',{x:[0,0.5],y:[0,2.5],xl:'time (s)',yl:'power ÷ starting power',sl:[['dt','Euler time step',0.001,0.01,0.001,0.009,function(v){return (v*1000).toFixed(0)+' ms'}]],series:[[2,'--muted',2,[6,4]],[1,'--accent',3]],solve:function(p){var r=0.001,n=1,C=PK.b/(PK.l*PK.L),t=0,rows=[[0,1,1]],dt=p.dt;while(t<0.5-1e-9){var dn=((r-PK.b)/PK.L)*n+PK.l*C,dC=(PK.b/PK.L)*n-PK.l*C;n+=dt*dn;C+=dt*dC;t+=dt;rows.push([t,isFinite(n)?n:NaN,pkExact(r,t)])}return rows},read:function(p,s){var bad=s.some(function(r){return !isFinite(r[1])||Math.abs(r[1])>3}),f=1-p.dt*(PK.b-0.001)/PK.L;return 'Step '+(p.dt*1000).toFixed(0)+' ms: the fast part is multiplied by <b>'+f.toFixed(2)+'</b> each step. '+(bad?'<b>Unstable:</b> the numbers blow up.':'Stable. Dashed line: exact answer.')},goal:function(p,s){return !s.some(function(r){return !isFinite(r[1])||Math.abs(r[1])>3})},goalMsg:'Find a time step small enough to be stable.'},`Insert 100 pcm and solve with Euler's method. Make the time step small enough.`,`Stiff equations need tiny steps with Euler. Real reactor codes use implicit methods that stay stable with big steps.`),
N(`β/Λ = 275 s⁻¹. Euler is stable if Δt × 275 < 2. Largest stable Δt, in ms?`,7.27,0.02,'ms',`2 ÷ 275 = 0.00727 s = 7.3 ms.`),
QE(`Prompt jump: a step of +ρ (below β) makes power jump by a factor of…`,[`β/(β − ρ)`,`ρ/(β − ρ)`,`β/(β + ρ)`,`(β − ρ)/β`],0,`Level 3 Maths. You can see the jump in the dashed curve.`),
T(`<h3>Key points</h3><ul><li><b>Euler</b>: y<sub>new</sub> = y + Δt·y′.</li><li>Point kinetics is <b>stiff</b>: millisecond and many-second time scales together.</li><li>Explicit Euler needs Δt below about 2Λ/β; implicit methods remove the limit.</li></ul>`)]),
LH('m5-1-3','The inhour equation',10,'The exact link between a reactivity step and the stable period that follows.',[
RM(`<ul><li>Stable period: power rises as e<sup>t/T</sup> after the prompt jump (Level 3 Maths).</li><li>Point kinetics equations; solutions of the form e<sup>ωt</sup>.</li></ul>`),
T(`<h3>Try n = e<sup>ωt</sup></h3><p>Substitute n ∝ e<sup>ωt</sup> and C ∝ e<sup>ωt</sup> into the point kinetics equations. Eliminating C leaves an equation linking reactivity to ω:</p><div class="eq">ρ = ωΛ + ωβ ÷ (ω + λ)</div><p>This is the (one-group) <b>inhour equation</b>. For six groups, the second term becomes a sum over the groups. The stable period is <b>T = 1/ω</b>, using the positive root.</p>`),
W('stepCalc',{steps:['Multiply out: ρ(ω + λ) = ωΛ(ω + λ) + ωβ','Rearrange into a quadratic: <div class="eq">Λω² + (Λλ + β − ρ)ω − ρλ = 0</div>','Small ρ: ωΛ terms are tiny, so (β − ρ)ω ≈ ρλ','<div class="eq">T = 1/ω ≈ (β − ρ) ÷ (λρ)</div>','ρ = 0.001 (100 pcm): T ≈ 0.0055 ÷ 0.00008 = <b>69 s</b>']},`Turn the inhour equation into a formula for the period.`),
W('fnPlot',{x:[10,800],y:[0.001,10000],ylog:true,xl:'reactivity (pcm)',yl:'stable period (s)',sl:[['r','Reactivity step (pcm)',10,800,10,100,function(v){return v+' pcm'}]],lines:[[1,'--muted']],curves:function(){return [[function(r){return 1/pkRoots(r*1e-5)[0]},'--accent',3],[function(r){return PK.L/(r*1e-5)},'--coral',2,[6,4]]]},marks:function(p,P,col){var c=P.c,T=1/pkRoots(p.r*1e-5)[0];c.fillStyle=col('--text');c.beginPath();c.arc(P.X(p.r),P.Y(T),6,0,7);c.fill()},read:function(p){var T=1/pkRoots(p.r*1e-5)[0];return p.r+' pcm: period <b>'+(T<1?T.toFixed(3):T.toFixed(1))+' s</b>. Dashed: what it would be with no delayed neutrons ('+sciH(PK.L/(p.r*1e-5))+' s).'}},`Change the reactivity step and read the stable period (one-group inhour).`),
N(`Using T ≈ (β − ρ)/(λρ) with β = 0.0065, λ = 0.08 s⁻¹, ρ = 0.0005, what is T, in seconds?`,150,0.01,'s',`0.006 ÷ (0.08 × 0.0005) = 0.006 ÷ 0.00004 = 150 s.`),
QE(`At ρ = β the reactor is…`,[`prompt critical`,`exactly critical`,`subcritical`,`shut down`],0,`Beyond 650 pcm the period collapses towards Λ/(ρ − β): the steep drop at the right of the graph.`),
T(`<h3>Key points</h3><ul><li><b>Inhour equation</b>: ρ = ωΛ + ωβ/(ω + λ) (one group).</li><li>Small ρ: <b>T ≈ (β − ρ)/(λρ)</b>.</li><li>Without delayed neutrons the period would be Λ/ρ: milliseconds. Delayed neutrons make it tens of seconds.</li></ul>`)])
]});
F('m5-1-1',[T(`<h3>Quick recap</h3><p>dn/dt = ((ρ − β)/Λ)n + λC; dC/dt = (β/Λ)n − λC.</p>`),Q(`Which term represents delayed neutrons arriving?`,[`λC`,`(β/Λ)n`,`−λC`,`ρ/Λ`],0,`Precursor decay.`),Q(`At steady state, C₀ is…`,[`βn₀/(λΛ)`,`n₀`,`zero`,`λn₀`],0,`Set derivatives to zero.`),Q(`Point kinetics treats the core as…`,[`a single point with one shape`,`many separate points`,`a slab`,`a fluid`],0,`Shape fixed.`)]);
F('m5-1-2',[T(`<h3>Quick recap</h3><p>Euler: y + Δt·y′. Stiff: Δt < 2Λ/β.</p>`),N(`dy/dt = −y, y = 1, Δt = 0.5. After one step?`,0.5,0.01,'',`1 − 0.5.`),Q(`A stiff equation has…`,[`very different time scales`,`no solution`,`only one time scale`,`constant values`],0,`ms and s.`),Q(`If Euler's growth factor is −1.5, errors…`,[`flip sign and grow`,`shrink`,`stay fixed`,`vanish`],0,`|−1.5| > 1.`)]);
F('m5-1-3',[T(`<h3>Quick recap</h3><p>T ≈ (β − ρ)/(λρ).</p>`),N(`ρ = 0.002, β = 0.0065, λ = 0.08. T?`,28.1,0.02,'s',`0.0045/0.00016.`),Q(`The stable period uses…`,[`the positive root ω`,`the negative root`,`both equally`,`neither`],0,`Negative root dies away.`),Q(`More reactivity gives a period that is…`,[`shorter`,`longer`,`unchanged`,`infinite`],0,`Faster rise.`)]);
TT('m5-1',[x('m5-1-1',Q(`β/Λ in a PWR is about…`,[`300 s⁻¹`,`0.08 s⁻¹`,`1 s⁻¹`,`10⁶ s⁻¹`],0,`0.0065/2e-5.`)),x('m5-1-1',N(`β = 0.006, λ = 0.1, Λ = 2 × 10⁻⁵. C₀/n₀?`,3000,0.01,'',`0.006/2e-6.`)),x('m5-1-2',Q(`Euler's method uses…`,[`the current gradient to step forward`,`the exact solution`,`random numbers`,`integration by parts`],0,`y + Δt y′.`)),x('m5-1-2',Q(`Codes avoid Euler's instability by using…`,[`implicit methods`,`bigger steps`,`fewer equations`,`no delayed neutrons`],0,`Stable for stiff problems.`)),x('m5-1-3',N(`ρ = 0.001, β = 0.0065, λ = 0.08: approximate period?`,68.75,0.02,'s',`0.0055/0.00008.`)),x('m5-1-3',Q(`The inhour equation links…`,[`reactivity and stable period`,`temperature and pressure`,`flux and power`,`boron and xenon`],0,`ρ(ω).`))]);

U({id:'m5-2',track:'maths',level:5,title:'Feedback and excursions',icon:'α·ΔT',color:'#D85A30',desc:'Adding temperature feedback to the kinetics equations, self-limiting power, and the maths of a prompt-critical burst.',lessons:[
LH('m5-2-1','Kinetics with feedback',10,'Let fuel temperature change reactivity, and the reactor settles itself at a new power.',[
RM(`<ul><li>Doppler (fuel temperature) coefficient: about −2 to −4 pcm/°C (Level 3 Theory).</li><li>Prompt jump approximation (Level 3 Maths).</li><li>Approaching equilibrium: dy/dt = a − by (Level 4 Maths).</li></ul>`),
T(`<h3>Closing the loop</h3><p>Reactivity is no longer fixed. It's the inserted reactivity plus feedback:</p><div class="eq">ρ(t) = ρ<sub>ext</sub> + α<sub>F</sub> ΔT<sub>fuel</sub>(t)</div><p>and the fuel temperature follows the power with a lag (the fuel time constant τ, a few seconds):</p><div class="eq">dΔT/dt = (θ (P − P₀) − ΔT) ÷ τ</div>${KY([['α<sub>F</sub>','fuel temperature (Doppler) coefficient','pcm/°C'],['θ','fuel temperature rise per % power at steady state','°C per %'],['τ','fuel thermal time constant','s']])}`),
W('odeSim',{x:[0,60],xl:'time (s)',yl:'power (% of full)',y:function(p,s){var m=100;s.forEach(function(r){if(r[1]>m)m=r[1]});return [0,Math.ceil(m*1.1/25)*25]},lines:[[100,'--muted']],sl:[['r','Reactivity inserted (pcm)',50,500,50,500,function(v){return v+' pcm'}],['a','Doppler coefficient (pcm/°C)',-4,-1,0.5,-1,function(v){return v.toFixed(1)}]],solve:function(p){var b=PK.b,l=PK.l,P0=50,c=b*P0/l,dT=0,t=0,dt=0.01,rows=[],th=6,tau=5;while(t<=60){var rho=(p.r+p.a*dT)*1e-5,n=l*c/(b-rho);if(t%0.25<dt)rows.push([t,n]);c+=dt*(b*n-l*c);dT+=dt*(th*(n-P0)-dT)/tau;t+=dt}return rows},read:function(p,s){var pk=0;s.forEach(function(r){if(r[1]>pk)pk=r[1]});var fin=s[s.length-1][1],ss=50+p.r/(6*-p.a);return 'Starts at 50%. Peak <b>'+pk.toFixed(0)+'%</b>, settles near <b>'+fin.toFixed(0)+'%</b> (formula: 50 + ρ/(|α|θ) = '+ss.toFixed(0)+'%).'},goal:function(p,s){return s[s.length-1][1]<100},goalMsg:'With 500 pcm inserted, find a Doppler coefficient that keeps the final power below 100%.'},`Insert reactivity at 50% power. Change the Doppler coefficient (θ = 6 °C per %, τ = 5 s; moderator feedback ignored).`,`A stronger negative coefficient means a smaller power rise for the same reactivity: the reactor limits itself.`),
W('stepCalc',{steps:['At the new steady state, total reactivity is zero: ρ<sub>ext</sub> + α<sub>F</sub>ΔT = 0','And ΔT = θ(P − P₀)','So ρ<sub>ext</sub> = |α<sub>F</sub>| θ (P − P₀)','<div class="eq">P = P₀ + ρ<sub>ext</sub> ÷ (|α<sub>F</sub>| θ)</div>','100 pcm, α = −2.5 pcm/°C, θ = 6 °C/%: P rises by 100 ÷ 15 ≈ <b>6.7%</b> of full power.']},`Find the new steady power.`),
N(`ρ<sub>ext</sub> = 300 pcm, |α| = 3 pcm/°C, θ = 5 °C per %. Power increase, in % of full power?`,20,0.01,'%',`300 ÷ (3 × 5) = 20%.`),
QE(`The steady value of dy/dt = a − by is…`,[`a/b`,`b/a`,`ab`,`0`],0,`Level 4 Maths.`),
T(`<h3>Key points</h3><ul><li>Feedback: <b>ρ = ρ<sub>ext</sub> + α<sub>F</sub>ΔT</b>, with ΔT lagging power.</li><li>New steady power: <b>P = P₀ + ρ<sub>ext</sub>/(|α|θ)</b>.</li><li>The lag allows an overshoot before feedback catches up.</li></ul>`)]),
LH('m5-2-2','Prompt-critical bursts',10,'If reactivity exceeds β, power rises in milliseconds. Feedback still ends the burst, and a neat formula says how much energy it releases.',[
RM(`<ul><li>Above prompt critical (ρ > β), period ≈ Λ/(ρ − β): milliseconds.</li><li>Kinetics with feedback.</li></ul>`),
T(`<h3>The Nordheim–Fuchs model</h3><p>For a very fast burst, ignore delayed neutrons and heat loss. All the energy E goes into heating the fuel, and feedback reduces reactivity in proportion to E. Solving gives a symmetrical pulse, and a remarkably simple result:</p><div class="eq">ΔT<sub>fuel</sub> = 2 (ρ₀ − β) ÷ |α<sub>F</sub>|</div>${KY([['ρ₀ − β','reactivity above prompt critical','(fraction)'],['α<sub>F</sub>','fuel temperature coefficient','per °C'],['ΔT<sub>fuel</sub>','total fuel temperature rise from the burst','°C']])}<p>The factor of 2: the burst only stops rising when feedback has cancelled the excess reactivity, and by symmetry it releases as much energy again on the way down. It ends with reactivity <b>as far below</b> prompt critical as it started above.</p>`),
W('stepCalc',{steps:['Reactivity 200 pcm above prompt critical: ρ₀ − β = 0.002','Doppler coefficient: −3 pcm/°C = −3 × 10<sup>−5</sup> per °C','ΔT = 2 × 0.002 ÷ (3 × 10<sup>−5</sup>)','= <b>133 °C</b> average fuel temperature rise','Pulse width ≈ 3.5Λ/(ρ₀ − β) = 3.5 × 2 × 10⁻⁵ ÷ 0.002 ≈ <b>35 ms</b>. Over in the blink of an eye.']},`Work out the fuel temperature rise from a burst.`),
N(`ρ₀ − β = 0.001, |α<sub>F</sub>| = 2 × 10⁻⁵ per °C. Fuel temperature rise, °C?`,100,0.01,'°C',`2 × 0.001 ÷ 2 × 10⁻⁵ = 100 °C.`),
Q(`What ends a prompt-critical burst in this model?`,[`Fuel temperature feedback`,'Delayed neutron emission','The operator\'s manual trip','Boron injection by the pumps'],0,`It happens too fast for anything else.`),
T(`<h3>Real examples</h3><ul><li><b>TRIGA</b> research reactors pulse safely to over 1,000 MW for milliseconds, thanks to a very strong negative fuel coefficient.</li><li>The SPERT tests in the 1960s deliberately caused bursts to check the theory.</li><li><b>Chernobyl</b> (1986) had a positive void coefficient: feedback made things worse, and the burst destroyed the reactor.</li></ul>`),
QE(`Prompt critical is reached when ρ equals…`,[`β`,`1`,`0`,`Λ`],0,`Level 3 Maths.`),
T(`<h3>Key points</h3><ul><li>Above prompt critical, power rises on a millisecond scale.</li><li><b>Nordheim–Fuchs</b>: ΔT = 2(ρ₀ − β)/|α|; pulse width ≈ 3.5Λ/(ρ₀ − β).</li><li>A strong negative fuel coefficient makes bursts self-limiting.</li></ul>`)]),
LH('m5-2-3','Rod ejection: energy into the fuel',10,'The fault where a control rod is forced out by pressure, and how safety limits are set on the energy the fuel absorbs.',[
RM(`<ul><li>Burst model: ΔT = 2(ρ₀ − β)/|α|.</li><li>Energy = mass × specific heat × temperature rise (Level 1).</li></ul>`),
T(`<h3>The fault</h3><p>In a PWR, control rod drives sit on top of the pressure vessel at 155 bar. If a drive housing broke, pressure could fire the rod out in about 0.1 s. That inserts the rod's local worth almost instantly: a <b>reactivity-initiated accident (RIA)</b>.</p><p>Designers limit rod worths, especially at hot zero power where rods are deepest, so that ejected worth stays limited.</p>`),
T(`<h3>Measuring damage: fuel enthalpy</h3><p>The key quantity is the energy deposited per gram of fuel, the <b>radially averaged fuel enthalpy</b> (in J/g or cal/g). Limits are set from experiments where fuel was pulsed in test reactors:</p><ul><li>a lower limit for <b>cladding failure</b> (tighter for high-burnup fuel, where cladding is weaker),</li><li>a higher limit to keep the core <b>coolable</b> (no fuel fragmenting into the coolant).</li></ul>`),
W('stepCalc',{steps:['Burst raises fuel temperature by 133 °C (last lesson).','UO₂ specific heat ≈ 0.3 J/(g·°C)','Energy deposited = 0.3 × 133 ≈ <b>40 J/g</b> (about 10 cal/g)','Experimental failure thresholds for fresh fuel are hundreds of J/g; for high-burnup fuel much lower.','So limiting rod worth and keeping a strong Doppler coefficient keeps the deposited energy well below limits.']},`Turn a temperature rise into deposited energy.`),
N(`A burst raises fuel temperature by 400 °C. c = 0.3 J/(g·°C). Energy deposited, J/g?`,120,0.01,'J/g',`0.3 × 400 = 120 J/g.`),
Q(`Why are rod ejection limits tighter for high-burnup fuel?`,[`The cladding is weaker (hydrided and corroded) and the pellet has more gas`,'It has more U-235 left in it, so the power spike is bigger','It is colder, so the cladding is more brittle and cracks open more easily when hit','Rods are worth less in old fuel, so ejecting one matters more'],0,`Pulse tests showed failures at lower energies.`),
QE(`At hot zero power, the Doppler feedback during a burst comes mainly from…`,[`fuel temperature rising`,`boron concentration falling`,`xenon building up quickly`,`the turbine taking more steam`],0,`It's the fastest feedback.`),
T(`<h3>Key points</h3><ul><li><b>Rod ejection</b> is a reactivity-initiated accident.</li><li>Damage is judged by <b>deposited fuel enthalpy</b> (J/g).</li><li>Rod worth limits + strong Doppler feedback keep it within limits.</li></ul>`)])
]});
F('m5-2-1',[T(`<h3>Quick recap</h3><p>P = P₀ + ρ/(|α|θ).</p>`),N(`ρ = 150 pcm, |α| = 2.5, θ = 6. Power rise (%)?`,10,0.01,'%',`150/15.`),Q(`Why can power overshoot before settling?`,[`Fuel temperature lags behind power`,`Delayed neutrons vanish`,`Boron is added`,`It can't`],0,`τ.`),Q(`A more negative α gives…`,[`a smaller power rise`,`a bigger rise`,`no change`,`instability`],0,`Stronger feedback.`)]);
F('m5-2-2',[T(`<h3>Quick recap</h3><p>ΔT = 2(ρ₀ − β)/|α|.</p>`),N(`ρ₀ − β = 0.003, |α| = 3 × 10⁻⁵. ΔT?`,200,0.01,'°C',`0.006/3e-5.`),Q(`After the burst, reactivity is…`,[`as far below prompt critical as it started above`,`exactly β`,`zero`,`still rising`],0,`Symmetry.`),Q(`TRIGA reactors pulse safely because…`,[`their fuel has a very strong negative coefficient`,`they have no control rods`,`they are huge`,`they use sodium`],0,`Self-limiting.`)]);
F('m5-2-3',[T(`<h3>Quick recap</h3><p>Energy = c × ΔT, in J/g.</p>`),N(`ΔT = 200 °C, c = 0.3. Energy (J/g)?`,60,0.01,'J/g',`0.3 × 200.`),Q(`RIA stands for…`,[`reactivity-initiated accident`,`reactor isolation alarm`,`radiation in air`,`rod insertion analysis`],0,`Rod ejection is one.`),Q(`Rod worths are most limited at…`,[`hot zero power`,`full power only`,`refuelling`,`never`],0,`Rods deepest.`)]);
TT('m5-2',[x('m5-2-1',Q(`With feedback, the new steady state has total reactivity…`,[`zero`,`ρ<sub>ext</sub>`,`β`,`negative forever`],0,`Critical again.`)),x('m5-2-1',N(`ρ = 200 pcm, |α| = 4, θ = 5. Power rise (%)?`,10,0.01,'%',`200/20.`)),x('m5-2-2',Q(`The Nordheim–Fuchs model ignores…`,[`delayed neutrons and heat loss`,`feedback`,`fuel`,`prompt neutrons`],0,`Too fast.`)),x('m5-2-2',N(`Pulse width ≈ 3.5Λ/(ρ₀ − β), Λ = 2 × 10⁻⁵, ρ₀ − β = 0.0035. Width in ms?`,20,0.01,'ms',`7e-5/0.0035 = 0.02 s.`)),x('m5-2-3',Q(`Rod ejection damage is measured by…`,[`fuel enthalpy (J/g)`,`boron ppm`,`pressure`,`flow`],0,`Energy per gram.`)),x('m5-2-3',Q(`A rod could be ejected by…`,[`primary pressure if its drive housing broke`,`gravity`,`the operator`,`xenon`],0,`155 bar.`))]);

U({id:'m5-3',track:'maths',level:5,title:'Two-group diffusion and reflectors',icon:'φ₁φ₂',color:'#1D9E75',desc:'Fast and thermal neutrons as two linked groups, reflector savings, and solving the diffusion equation on a computer.',lessons:[
LH('m5-3-1','Two energy groups',10,'Split neutrons into fast and thermal, link them by slowing down, and get a much better k.',[
RM(`<ul><li>One-group diffusion: −Dφ″ + Σ<sub>a</sub>φ = νΣ<sub>f</sub>φ/k (Level 4 Maths).</li><li>Neutrons are born fast and slow down (Level 4 Theory).</li><li>k = k∞/(1 + M²B²).</li></ul>`),
T(`<h3>Two linked equations</h3><p>Group 1 (fast) and group 2 (thermal). Fast neutrons are born from thermal fission, and are lost by absorption, leakage, or being <b>removed</b> into group 2 by slowing down:</p><div class="eq">−D₁φ₁″ + Σ<sub>r1</sub>φ₁ = (1/k) νΣ<sub>f2</sub>φ₂<br>−D₂φ₂″ + Σ<sub>a2</sub>φ₂ = Σ<sub>12</sub>φ₁</div>${KY([['φ₁, φ₂','fast and thermal flux','n/cm²/s'],['Σ<sub>12</sub>','slowing down from fast to thermal','cm⁻¹'],['Σ<sub>r1</sub>','fast removal: Σ<sub>a1</sub> + Σ<sub>12</sub>','cm⁻¹'],['Σ<sub>a2</sub>','thermal absorption','cm⁻¹']],'Fast fission is ignored here for simplicity.')}`),
W('stepCalc',{steps:['In an infinite core (no leakage), drop the φ″ terms.','Thermal: φ₂ = Σ<sub>12</sub>φ₁ ÷ Σ<sub>a2</sub>','Fast: Σ<sub>r1</sub>φ₁ = νΣ<sub>f2</sub>φ₂ ÷ k∞','Substitute: <div class="eq">k∞ = νΣ<sub>f2</sub> Σ<sub>12</sub> ÷ (Σ<sub>r1</sub> Σ<sub>a2</sub>)</div>','Read it as: (fraction of fast neutrons that slow down) × (fission neutrons per thermal absorption).']},`Find k∞ for two groups.`),
N(`νΣ<sub>f2</sub> = 0.175, Σ<sub>12</sub> = 0.018, Σ<sub>r1</sub> = 0.026, Σ<sub>a2</sub> = 0.1 (all cm⁻¹). k∞? (3 d.p.)`,1.212,0.003,'',`0.175 × 0.018 ÷ (0.026 × 0.1) = 0.00315 ÷ 0.0026 = 1.212.`),
T(`<h3>With leakage</h3><p>For a bare core with buckling B²:</p><div class="eq">k = k∞ ÷ [(1 + L₁²B²)(1 + L₂²B²)]</div>${KY([['L₁² = D₁/Σ<sub>r1</sub>','fast diffusion area (about 50 cm² in a PWR)','cm²'],['L₂² = D₂/Σ<sub>a2</sub>','thermal diffusion area (a few cm²)','cm²']])}<p>Most leakage happens while neutrons are fast: they travel much further before slowing down than afterwards.</p>`),
QE(`M² is about 60 cm² in a PWR. That's roughly…`,[`L₁² + L₂²`,`L₁² × L₂²`,`L₁²/L₂²`,`1/B²`],0,`Migration area = fast + thermal diffusion areas.`),
T(`<h3>Key points</h3><ul><li>Two groups: fast (removed by slowing down) and thermal.</li><li><b>k∞ = νΣ<sub>f2</sub>Σ<sub>12</sub>/(Σ<sub>r1</sub>Σ<sub>a2</sub>)</b>.</li><li>Leakage: (1 + L₁²B²)(1 + L₂²B²); fast leakage dominates.</li></ul>`)]),
LH('m5-3-2','Reflectors',10,'Surround the core with something that bounces neutrons back, and the core needs less fuel.',[
RM(`<ul><li>Bare slab flux: cos(πx/a) (Level 4 Maths).</li><li>k = k∞/(1 + M²B²); smaller B² → less leakage.</li></ul>`),
T(`<h3>Reflector savings</h3><p>A <b>reflector</b> scatters escaping neutrons back into the core. The core then behaves like a <b>bigger bare core</b>: each side gains a distance δ called the <b>reflector savings</b>. For a reflector of thickness T (with similar diffusion coefficients):</p><div class="eq">δ ≈ M<sub>r</sub> tanh(T / M<sub>r</sub>)</div>${KY([['δ','reflector savings','cm'],['M<sub>r</sub>','migration length in the reflector (about 6 cm for water)','cm'],['T','reflector thickness','cm']],'tanh rises from 0 and levels off at 1, so very thick reflectors give δ → M<sub>r</sub>.')}`),
W('fnPlot',{x:[-80,80],y:[0,1.1],xl:'position (cm)',yl:'flux ÷ centre flux',sl:[['T','Reflector thickness (cm)',0,30,2,0,function(v){return v+' cm'}]],curves:function(p){var a=100,M=6,d=M*Math.tanh(p.T/M),B=Math.PI/(a+2*d),edge=Math.cos(B*a/2);return [[function(x){return Math.abs(x)>a/2?NaN:Math.cos(Math.PI*x/a)},'--muted',2,[6,4]],[function(x){var ax=Math.abs(x);if(ax<=a/2)return Math.cos(B*x);if(ax<=a/2+p.T&&p.T>0)return edge*Math.sinh((a/2+p.T-ax)/M)/Math.sinh(p.T/M);return NaN},'--accent',3]]},marks:function(p,P,col){var c=P.c;c.strokeStyle=col('--muted');c.setLineDash([2,3]);[-50,50].forEach(function(x){c.beginPath();c.moveTo(P.X(x),P.Y(0));c.lineTo(P.X(x),P.Y(1.1));c.stroke()});c.setLineDash([])},read:function(p){var d=6*Math.tanh(p.T/6),B2=Math.pow(Math.PI/(100+2*d),2),k=1.05/(1+60*B2);return 'Reflector '+p.T+' cm: δ = <b>'+d.toFixed(1)+' cm</b>. 100 cm core, k∞ = 1.05, M² = 60 cm²: k = <b>'+k.toFixed(4)+'</b> '+(k>=1?'(critical or above)':'(subcritical)')},goal:function(p){var d=6*Math.tanh(p.T/6);return 1.05/(1+60*Math.pow(Math.PI/(100+2*d),2))>=1},goalMsg:'Add enough reflector to make this core critical.'},`This 100 cm slab is subcritical when bare. Add a reflector (dotted lines: core edges; dashed: bare flux).`,`The reflector flattens the flux and makes up for the leakage: the same core is now critical.`),
T(`<h3>Reflectors at Hinkley Point C</h3><p>The EPR surrounds its core with a <b>heavy stainless-steel reflector</b> instead of the usual water gap. It reflects neutrons back (improving fuel use) and shields the pressure vessel from fast neutrons, reducing embrittlement (Level 4 Theory).</p>`),
N(`M<sub>r</sub> = 6 cm, very thick reflector. Roughly how much smaller (in cm) can a slab core be than a bare critical one? (2δ)`,12,0.02,'cm',`δ → M<sub>r</sub> = 6 cm on each side: 12 cm in total.`),
QE(`Irradiation of vessel steel raises its…`,[`ductile–brittle transition temperature`,`thermal conductivity and toughness`,`density and elastic stiffness`,`boron content near the inner surface`],0,`Level 4 Theory.`),
T(`<h3>Key points</h3><ul><li>A reflector makes a core act like a bare core 2δ wider.</li><li><b>δ ≈ M<sub>r</sub>tanh(T/M<sub>r</sub>)</b>; levels off after 2–3 migration lengths.</li><li>EPR: heavy steel reflector, which saves fuel and protects the vessel.</li></ul>`)]),
LH('m5-3-3','Solving diffusion on a computer',10,'Turn the diffusion equation into a matrix, then let the computer find k by repeating one simple step.',[
RM(`<ul><li>φ″: the second derivative (Level 4 Maths).</li><li>Diffusion equation −Dφ″ + Σ<sub>a</sub>φ = νΣ<sub>f</sub>φ/k.</li></ul>`),
T(`<h3>Finite differences</h3><p>Divide the core into a mesh of points spaced h apart. The second derivative at point i is approximately:</p><div class="eq">φ″ ≈ (φ<sub>i+1</sub> − 2φ<sub>i</sub> + φ<sub>i−1</sub>) ÷ h²</div><p>Every point gives one equation linking it to its neighbours. Together they form a matrix equation: <b>Aφ = (1/k)Fφ</b>.</p>`),
T(`<h3>Power iteration</h3><ol class="steps"><li>Guess a flux shape φ and a value of k.</li><li>Work out the fission source F φ ÷ k.</li><li>Solve A φ<sub>new</sub> = source (a tridiagonal matrix: quick to solve).</li><li>Update k<sub>new</sub> = k × (total new source ÷ total old source).</li><li>Repeat until φ and k stop changing.</li></ol><p>This is how real core design codes find k and the power shape, in 3-D with millions of mesh points.</p>`),
W('fnPlot',{x:[0,100],y:[0,1.1],xl:'position (cm)',yl:'flux ÷ peak',sl:[['n','Iterations',0,30,1,0,function(v){return v}]],curves:function(p){var r=fdPower(p.n);return [[function(x){return Math.sin(Math.PI*x/100)},'--muted',2,[6,4]],[function(x){var u=x/r.h,i=Math.floor(u),f=u-i,v=function(j){return j<=0||j>r.phi.length?0:r.phi[j-1]};return v(i)*(1-f)+v(i+1)*f},'--accent',3]]},read:function(p){var r=fdPower(p.n),ex=1.125/(1+50*Math.pow(Math.PI/100,2));return p.n+' iterations: k = <b>'+r.k.toFixed(5)+'</b> (analytic: '+ex.toFixed(5)+'). Starting guess was badly skewed.'},goal:function(p){var ex=1.125/(1+50*Math.pow(Math.PI/100,2));return Math.abs(fdPower(p.n).k-ex)<2e-4},goalMsg:'Keep iterating until k agrees with the analytic answer to 4 decimal places.'},`Run power iteration on a 100 cm slab (dashed: exact flux shape). Start from a bad guess.`,`Each iteration pulls the shape towards the fundamental mode. That's how every core design code finds k.`),
N(`Mesh h = 2 cm. Flux values 0.90, 1.00, 0.90 at points i−1, i, i+1. Estimate φ″ at i.`,-0.05,0.01,'per cm²',`(0.90 − 2 + 0.90) ÷ 4 = −0.2 ÷ 4 = −0.05.`),
QE(`For a slab of width a, the exact flux shape is…`,[`a cosine (or sine from one edge)`,`a straight line (falling from the middle)`,`flat (the same everywhere)`,`exponential (falling from one edge)`],0,`Level 4 Maths.`),
T(`<h3>Key points</h3><ul><li><b>Finite differences</b>: φ″ ≈ (φ<sub>i+1</sub> − 2φ<sub>i</sub> + φ<sub>i−1</sub>)/h².</li><li><b>Power iteration</b>: solve, update k, repeat until converged.</li><li>Converges to the fundamental flux shape whatever the starting guess.</li></ul>`)])
]});
F('m5-3-1',[T(`<h3>Quick recap</h3><p>k∞ = νΣ<sub>f2</sub>Σ<sub>12</sub>/(Σ<sub>r1</sub>Σ<sub>a2</sub>).</p>`),Q(`Σ<sub>r1</sub> includes…`,[`fast absorption and slowing down`,`only fission`,`thermal absorption`,`leakage`],0,`Removal.`),N(`k∞ = 1.2, L₁²B² = 0.1, L₂²B² = 0.01. k? (3 d.p.)`,1.08,0.003,'',`1.2/(1.1 × 1.01).`),Q(`Most leakage happens…`,[`while neutrons are fast`,`after thermalisation`,`never`,`in the reflector only`],0,`L₁² ≫ L₂².`)]);
F('m5-3-2',[T(`<h3>Quick recap</h3><p>δ ≈ M<sub>r</sub>tanh(T/M<sub>r</sub>).</p>`),N(`M<sub>r</sub> = 6, T = 6 cm. δ? (tanh 1 = 0.762)`,4.57,0.02,'cm',`6 × 0.762.`),Q(`A reflector makes the flux near the core edge…`,[`higher (flatter shape)`,`lower`,`zero`,`unchanged`],0,`Neutrons come back.`),Q(`The EPR's reflector is made of…`,[`stainless steel`,`graphite`,`beryllium`,`lead`],0,`Heavy reflector.`)]);
F('m5-3-3',[T(`<h3>Quick recap</h3><p>Mesh + finite differences + power iteration.</p>`),Q(`Power iteration converges to…`,[`the fundamental mode`,`the starting guess`,`zero`,`a random shape`],0,`Dominant eigenvalue.`),Q(`Each mesh equation links a point to…`,[`its neighbours`,`every other point`,`only itself`,`the boundary only`],0,`Tridiagonal.`),N(`φ = 1, 0.8, 0.5 at i−1, i, i+1, h = 1 cm. φ″ at i?`,-0.1,0.01,'',`(0.5 − 1.6 + 1)/1.`)]);
TT('m5-3',[x('m5-3-1',Q(`In two-group theory, the thermal group's source is…`,[`neutrons slowing down from the fast group`,`fission`,`the reflector`,`delayed neutrons`],0,`Σ<sub>12</sub>φ₁.`)),x('m5-3-1',N(`νΣ<sub>f2</sub> = 0.15, Σ<sub>12</sub> = 0.02, Σ<sub>r1</sub> = 0.025, Σ<sub>a2</sub> = 0.1. k∞?`,1.2,0.003,'',`0.003/0.0025.`)),x('m5-3-2',Q(`Reflector savings levels off because…`,[`tanh approaches 1 for thick reflectors`,`neutrons stop`,`D changes`,`k falls`],0,`Beyond a few M<sub>r</sub>.`)),x('m5-3-2',Q(`A reflected core compared with a bare one needs…`,[`less fuel to be critical`,`more fuel`,`the same`,`no fuel`],0,`Less leakage.`)),x('m5-3-3',Q(`In power iteration, k is updated using…`,[`the ratio of new to old fission source`,`a guess each time`,`the boron concentration`,`the mesh size`],0,`k × S<sub>new</sub>/S<sub>old</sub>.`)),x('m5-3-3',Q(`The finite-difference matrix for 1-D diffusion is…`,[`tridiagonal`,`full`,`diagonal only`,`random`],0,`Neighbours only.`))]);

U({id:'m5-4',track:'maths',level:5,title:'Reliability and risk',icon:'P(f)',color:'#BA7517',desc:'Failure rates, standby unavailability, redundancy and common cause failure, fault trees and event trees.',lessons:[
LH('m5-4-1','Failure rates and unavailability',10,'Turning "how often does it break" into "what\'s the chance it won\'t work when we need it".',[
RM(`<ul><li>Exponential decay: N = N₀e<sup>−λt</sup> (Level 2 Maths).</li><li>Probability: 0 = impossible, 1 = certain.</li></ul>`),
T(`<h3>Failure rate</h3><p>Many components fail randomly at a constant rate λ (failures per hour). Then the probability of still working after time t is:</p><div class="eq">R(t) = e<sup>−λt</sup> &nbsp;&nbsp; and failure probability F(t) = 1 − e<sup>−λt</sup> ≈ λt (when λt is small)</div>${KY([['λ','failure rate','per hour'],['R(t)','reliability: probability of no failure by time t',''],['MTTF = 1/λ','mean time to failure','hours']],'Same maths as radioactive decay!')}`),
T(`<h3>Standby equipment</h3><p>Safety pumps and diesels sit waiting. A failure while waiting is <b>hidden</b> until a test or a real demand. If tested every T hours, a hidden failure has on average been there for T/2, so the average <b>unavailability</b> is:</p><div class="eq">Q ≈ λT / 2</div>`),
W('fnPlot',{x:[0,12],y:[0,0.005],xl:'test interval (months)',yl:'average unavailability',sl:[['T','Test interval (months)',1,12,1,3,function(v){return v+' month'+(v>1?'s':'')}]],curves:function(){return [[function(m){return 1e-6*m*730/2},'--accent',3]]},marks:function(p,P,col){var c=P.c;c.fillStyle=col('--coral');c.beginPath();c.arc(P.X(p.T),P.Y(1e-6*p.T*730/2),6,0,7);c.fill()},read:function(p){var q=1e-6*p.T*730/2;return 'λ = 10⁻⁶ per hour. Tested every '+p.T+' month'+(p.T>1?'s':'')+': Q = <b>'+sciH(q)+'</b> (about 1 in '+Math.round(1/q)+' demands).'}},`Change how often a standby pump is tested.`),
N(`λ = 2 × 10⁻⁵ per hour, tested every 1,000 hours. Average unavailability Q?`,0.01,0.01,'',`2 × 10⁻⁵ × 1,000 ÷ 2 = 0.01.`),
QE(`e<sup>−x</sup> ≈ 1 − x when…`,[`x is small`,`x is large`,`x = 1`,`always`],0,`So F ≈ λt.`),
T(`<h3>Key points</h3><ul><li><b>R = e<sup>−λt</sup></b>; F ≈ λt for small λt.</li><li>Standby: hidden failures; <b>Q ≈ λT/2</b>.</li><li>Testing more often lowers Q (but testing itself causes wear and risk).</li></ul>`)]),
LH('m5-4-2','Redundancy and common cause',10,'Four independent trains should be incredibly reliable. Common cause failures are why they aren\'t quite.',[
RM(`<ul><li>Unavailability Q of one train.</li><li>EPR safety systems have four separate trains (Level 1 Theory).</li></ul>`),
T(`<h3>Independent trains</h3><p>If any one of n trains is enough, the system fails only if <b>all</b> fail. If they're independent:</p><div class="eq">Q<sub>system</sub> = Q<sup>n</sup></div><p>With Q = 0.01: two trains 10⁻⁴; four trains 10⁻⁸. Too good to be true.</p>`),
T(`<h3>Common cause failure (CCF)</h3><p>A shared cause (the same design flaw, the same maintenance error, flooding of a room) can knock out several trains at once. The simplest model is the <b>β-factor model</b>: a fraction β of each train's failures hit all trains together:</p><div class="eq">Q<sub>system</sub> ≈ Q<sup>n</sup> + βQ</div>${KY([['β','common cause fraction, typically 0.01–0.1','']],'Not the delayed neutron β! Same letter, different subject.')}`),
W('fnPlot',{x:[0.5,4.5],y:[1e-9,0.1],ylog:true,xl:'number of redundant trains',yl:'system unavailability',sl:[['b','Common cause fraction β',0,0.2,0.01,0,function(v){return v.toFixed(2)}]],curves:function(){return []},marks:function(p,P,col){var c=P.c,Q=0.01;for(var n=1;n<=4;n++){var qi=Math.pow(Q,n),qc=n>1?qi+p.b*Q:Q;c.fillStyle=col('--muted');c.beginPath();c.arc(P.X(n),P.Y(qi),5,0,7);c.fill();c.fillStyle=col('--accent');c.beginPath();c.arc(P.X(n),P.Y(qc),8,0,7);c.fill()}},read:function(p){var Q=0.01,q4=Math.pow(Q,4)+(p.b>0?p.b*Q:0);return 'One train Q = 0.01. Four trains: <b>'+sciH(q4)+'</b> (grey dots: if fully independent). '+(p.b>0?'Common cause sets a floor of βQ = '+sciH(p.b*Q)+'.':'With β = 0, extra trains look amazing…')},goal:function(p){return p.b>=0.05},goalMsg:'Set a realistic β (0.05 or more) and see what happens to four trains.'},`Big dots: real system. Grey dots: if trains were truly independent. Add common cause.`,`Common cause failures put a floor under reliability: beyond two or three trains, diversity matters more than more copies.`),
T(`<h3>Defences against CCF</h3><ul><li><b>Diversity</b>: different designs doing the same job (e.g. diesel generators and separate station blackout diesels of a different make).</li><li><b>Physical separation</b>: EPR trains are in separate buildings, so a fire or flood can't take out all four.</li><li><b>Staggered testing and maintenance</b> by different teams.</li></ul>`),
N(`Q = 0.01 per train, β = 0.1, two trains. System Q? (Q² + βQ)`,0.0011,0.01,'',`0.0001 + 0.001 = 0.0011.`),
QE(`Average standby unavailability = …`,[`λT/2`,`λT`,`2λT`,`e<sup>−λT</sup>`],0,`Last lesson.`),
T(`<h3>Key points</h3><ul><li>Independent: <b>Q<sup>n</sup></b>. With common cause: <b>Q<sup>n</sup> + βQ</b>.</li><li>CCF usually dominates highly redundant systems.</li><li>Defend with diversity, separation and staggered testing.</li></ul>`)]),
LH('m5-4-3','Fault trees and event trees',10,'Two kinds of diagram that turn a whole plant into a probability calculation.',[
RM(`<ul><li>Independent events both happening: multiply probabilities.</li><li>Either of two rare events: add probabilities (approximately).</li></ul>`),
T(`<h3>Fault trees: working down</h3><p>Start with an undesired <b>top event</b> ("no emergency feedwater") and ask "how could that happen?". Combine causes with:</p><ul><li><b>AND gates</b>: all inputs needed → multiply.</li><li><b>OR gates</b>: any input is enough → add (for rare events).</li></ul><p>A <b>minimal cut set</b> is a smallest combination of failures that causes the top event.</p>`),
W('stepCalc',{steps:['Top event: no emergency feedwater (two pump trains, either enough).','= Train A fails <b>AND</b> Train B fails','Each train fails if: pump fails (0.003) <b>OR</b> valve fails (0.002) <b>OR</b> power lost (0.005) → 0.01','Independent: 0.01 × 0.01 = 10<sup>−4</sup>','Plus a common-cause cut set (both pumps, β = 0.05): 0.05 × 0.003 = 1.5 × 10<sup>−4</sup>. Total ≈ <b>2.5 × 10<sup>−4</sup></b> per demand. Common cause dominates!']},`Work through a small fault tree.`),
T(`<h3>Event trees: working forwards</h3><p>Start with an <b>initiating event</b> (e.g. loss of off-site power, about 0.05 per year) and branch at each safety function: success or failure. Multiply along each path to get its frequency. Paths that end in core damage add up to the <b>core damage frequency (CDF)</b>.</p>`),
W('stepCalc',{steps:['Initiating event: loss of off-site power, 0.05 per year.','Diesels fail to supply power: 10<sup>−3</sup>','Then the separate station blackout diesels fail too: 10<sup>−2</sup>','Then batteries run out before power is restored: 0.3','Path frequency: 0.05 × 10<sup>−3</sup> × 10<sup>−2</sup> × 0.3 = <b>1.5 × 10<sup>−7</sup> per year</b>']},`Follow one path through an event tree.`),
N(`Initiating event 0.1 per year, then failures with probabilities 10⁻² and 10⁻³. Path frequency per year? Give the number in front of × 10⁻⁶.`,1,0.01,'× 10⁻⁶ per year',`0.1 × 10⁻² × 10⁻³ = 10⁻⁶.`),
QE(`With β = 0.1 and Q = 0.01, the common cause term βQ is…`,[`10<sup>−3</sup>`,`10<sup>−4</sup>`,`0.1`,`10<sup>−8</sup>`],0,`Last lesson.`),
T(`<h3>Key points</h3><ul><li><b>Fault tree</b>: top event, AND (multiply), OR (add); minimal cut sets.</li><li><b>Event tree</b>: initiating event → branches → path frequencies.</li><li>Summed core-damage paths give the <b>CDF</b> (next level of detail in Theory: PSA).</li></ul>`)])
]});
